use crate::{bq086 as b,catalog,model::*,rules::*,unit_support::*};
use crate::jc029_tests::{pass_top,envelope};
fn grave(g:&mut Game,id:&str,seat:usize)->String{let c=g.make_card(id,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
fn research(g:&mut Game,seat:usize)->String{let c=g.make_card("BQ091",seat);let id=c.id.clone();g.attachments.push(Attachment{card:c,host_id:g.regions[0].card.id.clone()});id}
fn setup()->(Game,String,String,String){let mut g=game();fund(&mut g,0,"JC096",6);let source=held(&mut g,b::ID,0);let corpse=grave(&mut g,"XQ46",0);let host=research(&mut g,0);(g,source,corpse,host)}
fn entry()->(Game,String,String){let(mut g,id,corpse,host)=setup();act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});pass_top(&mut g);(g,corpse,host)}
fn death(seat:usize,hidden:bool)->Game{let mut g=game();field(&mut g,b::ID,0);let dead=field(&mut g,"JC125",seat);g.board_mut(&dead).unwrap().face_down=hidden;g.remove_dead(&dead,RemovalCause::Destroy);g.drive().unwrap();restore(&mut g);g}
fn invalid(base:&Game,g:&Game){let bytes=serde_json::to_string(g).unwrap();assert!(Game::from_persisted(&bytes).is_err());let mut room=envelope(base);room.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}
#[test]
fn bq086_paid_entry_binds_two_targets_before_response_and_seals_real_corpse(){let(mut g,corpse,host)=entry();assert_eq!(g.resources(0),0);choose(&mut g,vec![corpse.clone()]);assert!(g.stack.is_empty());assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq086-host");choose(&mut g,vec![host.clone()]);let f=g.stack.last().unwrap().frame.as_ref().unwrap();assert_eq!(f.targets.iter().map(|t|t.id.clone()).collect::<Vec<_>>(),vec![corpse.clone(),host.clone()]);assert!(g.players[0].graveyard.iter().any(|c|c.id==corpse));pass_top(&mut g);assert!(!g.players[0].graveyard.iter().any(|c|c.id==corpse));assert!(g.sealed_cards.iter().any(|s|s.card.definition=="XQ46"&&s.card.id!=corpse&&s.host_id==host));restore(&mut g);}
#[test]
fn bq086_entry_excludes_teammate_host_and_other_grave_and_can_decline_either_stage(){for second in [false,true]{let(mut g,id,corpse,host)=setup();let ally=research(&mut g,1);let enemy=research(&mut g,2);let other=grave(&mut g,"XQ46",1);let wrong=grave(&mut g,"JC001",0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});pass_top(&mut g);let options=&g.pending.as_ref().unwrap().choice.options;assert!(options.iter().any(|o|o.id==corpse));assert!(options.iter().all(|o|o.id!=other&&o.id!=wrong));if second{choose(&mut g,vec![corpse.clone()]);let options=&g.pending.as_ref().unwrap().choice.options;assert!(options.iter().any(|o|o.id==host));assert!(options.iter().all(|o|o.id!=ally&&o.id!=enemy));}choose(&mut g,vec![]);assert!(g.pending.is_none()&&g.stack.is_empty()&&g.sealed_cards.is_empty());restore(&mut g);}}
#[test]
fn bq086_no_research_host_does_not_offer_incomplete_target(){let(mut g,id,_,_)=setup();g.attachments.clear();research(&mut g,1);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});pass_top(&mut g);assert!(g.pending.is_none()&&g.stack.is_empty());}
#[test]
fn bq086_response_target_removal_cancels_without_rebinding(){for host_lost in [false,true]{let(mut g,corpse,host)=entry();choose(&mut g,vec![corpse.clone()]);choose(&mut g,vec![host.clone()]);if host_lost{g.attachments.retain(|a|a.card.id!=host);research(&mut g,0);}else{g.players[0].graveyard.retain(|c|c.id!=corpse);grave(&mut g,"XQ46",0);}restore(&mut g);pass_top(&mut g);assert!(g.sealed_cards.is_empty());}}
#[test]
fn bq086_only_personal_face_up_character_death_observes(){for seat in 0..4{for hidden in [false,true]{let g=death(seat,hidden);assert_eq!(g.pending.is_some(),seat==0&&!hidden);}}}
#[test]
fn bq086_enemy_chooses_own_character_or_hidden_and_not_teammate(){for hidden in [false,true]{let mut g=game();field(&mut g,b::ID,0);let victim=field(&mut g,"JC125",0);let chosen=field(&mut g,"JC125",2);g.board_mut(&chosen).unwrap().face_down=hidden;let ally=field(&mut g,"JC125",3);g.remove_dead(&victim,RemovalCause::Destroy);g.drive().unwrap();assert!(g.pending.as_ref().unwrap().choice.options.iter().all(|o|o.id=="p2"||o.id=="p3"));choose(&mut g,vec!["p2".into()]);pass_top(&mut g);assert_eq!(g.pending.as_ref().unwrap().seat,2);assert_eq!(g.pending.as_ref().unwrap().choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>(),vec![chosen.clone()]);choose(&mut g,vec![chosen.clone()]);assert!(g.board(&chosen).is_none()&&g.board(&ally).is_some());assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}}
#[test]
fn bq086_empty_target_player_and_declined_death_have_no_phantom_choice(){for accept in [false,true]{let mut g=death(0,false);choose(&mut g,if accept{vec!["p2".into()]}else{vec![]});if accept{pass_top(&mut g);}assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}}
#[test]
fn bq086_simultaneous_self_and_other_death_freeze_two_observations(){let mut g=game();let source=field(&mut g,b::ID,0);let other=field(&mut g,"JC125",0);let rows=[source.clone(),other].into_iter().map(|id|{let(r,c)=g.board(&id).unwrap();let snap=g.source_snapshot(c,Some(r));(id,RemovalCause::Destroy,snap)}).collect();g.remove_death_batch(rows);let ds=g.effects.iter().filter_map(|e|match e{Effect::Declare{declaration:d}if d.ability.key==b::DEATH=>Some(d),_=>None}).collect::<Vec<_>>();assert_eq!(ds.len(),2);assert!(ds.iter().all(|d|d.source.card.id==source));restore(&mut g);}
#[test]
fn bq086_pending_observation_and_second_target_tamper_rejected_in_game_and_room(){let(mut g,corpse,_)=entry();choose(&mut g,vec![corpse]);for n in 0..4{let mut bad=g.clone();match n{0=>bad.pending.as_mut().unwrap().seat=1,1=>bad.pending.as_mut().unwrap().choice.options.clear(),_=>{let ChoiceResolution::Declare{stage:DeclareChoice::BQ086Host{corpse},..}=&mut bad.pending.as_mut().unwrap().resolution else{panic!()};if n==2{corpse.id="i1".into();}else{corpse.spec.relation=Relation::Any;}}}invalid(&g,&bad);}
 let g=death(0,false);for n in 0..3{let mut bad=g.clone();let ChoiceResolution::Declare{declaration:d,..}=&mut bad.pending.as_mut().unwrap().resolution else{panic!()};let Op::BQ086Death{observation:Some(o)}=&mut d.ability.ops[0]else{panic!()};match n{0=>o.dead.controller=1,1=>o.turn+=1,_=>o.dead.face_down=true};invalid(&g,&bad);}}
#[test]
fn bq086_actual_paid_card_rejects_foreign_or_missing_frame(){let(mut g,id,_,_)=setup();act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});for n in 0..2{let mut bad=g.clone();let item=bad.stack.last_mut().unwrap();if n==0{item.frame=None;}else{item.frame.as_mut().unwrap().source.card.definition="JC001".into();}invalid(&g,&bad);}}
#[test]
fn bq086_closed_whole_definition_original_icons_wound_and_scope(){let c=catalog::card(b::ID);assert!(!c.supported&&c.unique);assert_eq!((c.cost,c.defense,c.rule_traits.wound),(6,Some(3),1));assert_eq!(c.loyalty,["黑色","黑色","黑色"]);assert_eq!(c.subtitle.as_deref(),Some("黄衣死神"));for n in 0..3{let mut ds=definitions().clone();let d=ds.get_mut(b::ID).unwrap();match n{0=>d.abilities[1].targets.pop(),1=>{d.abilities[1].targets[1].relation=Relation::FriendlyTeam;None},_=>{d.traits.wound=0;None}};assert!(validate_definitions(&ds).is_err());}}
#[test]
fn bq086_sacrifice_pending_wrong_seat_payload_duplicate_frame_are_rejected(){let mut g=game();field(&mut g,b::ID,0);let victim=field(&mut g,"JC125",0);field(&mut g,"JC125",2);g.remove_dead(&victim,RemovalCause::Destroy);g.drive().unwrap();choose(&mut g,vec!["p2".into()]);pass_top(&mut g);for n in 0..4{let mut bad=g.clone();match n{0=>bad.pending.as_mut().unwrap().seat=0,1=>bad.pending.as_mut().unwrap().choice.options.clear(),_=>{let ChoiceResolution::Frame{frame,..}=&mut bad.pending.as_mut().unwrap().resolution else{panic!()};if n==2{frame.targets[0].public.controller=Some("p0".into());}else{bad.effects.push_back(Effect::Frame{frame:frame.clone()});}}}invalid(&g,&bad);}let p=g.pending.clone().unwrap();let id=p.choice.options[0].id.clone();reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![id.clone()]),..Action::new("choose")});reject(&mut g,2,Action{choice_id:Some(p.choice.id),selected:Some(vec![id]),amount:Some(7),..Action::new("choose")});}
#[test]
fn bq086_real_combat_uses_wound_marker_without_extra_kill_damage(){let mut g=game();let source=field(&mut g,b::ID,0);let target=field(&mut g,"JC125",2);assert_eq!(g.effective_wound(g.board(&source).unwrap().1),1);assert_eq!(g.effective_kill(g.board(&source).unwrap().1),0);g.begin_window(Window::Before(0,1));g.close_window().unwrap();g.drive().unwrap();let p=g.pending.clone().unwrap();assert_eq!(p.choice.amount,Some(1));assert!(matches!(&p.resolution,ChoiceResolution::Damage{wound_sources,..}if wound_sources==&vec![source]));act(&mut g,p.seat,Action{choice_id:Some(p.choice.id),allocations:Some(std::collections::BTreeMap::from([(target.clone(),1)])),..Action::new("choose")});assert!(g.board(&target).is_none());restore(&mut g);}
#[test]
fn bq086_native_room_witness(){
 use crate::{abi112_review_play_tests::Trace,room::{RoomEnvelope,RoomCommand}};use sha2::{Digest,Sha256};let mut cases=vec![];
 let(g,id,corpse,host)=setup();let mut t=Trace::new(g,"bq086-entry-double-target".into(),860);t.action(0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});t.until_pending();t.choose(vec![corpse]);assert!(t.room.game.stack.is_empty());t.choose(vec![host.clone()]);while !t.room.game.stack.is_empty(){t.pass();}assert!(t.room.game.sealed_cards.iter().any(|s|s.card.definition=="XQ46"&&s.host_id==host));cases.push(t.value());
 for hidden in [false,true]{let mut g=game();field(&mut g,b::ID,0);let dead=field(&mut g,"JC125",0);let enemy=field(&mut g,"JC125",2);g.board_mut(&enemy).unwrap().face_down=hidden;fund(&mut g,0,"JC096",2);let spell=held(&mut g,"JZ54",0);let mut t=Trace::new(g,format!("bq086-real-sacrifice-{hidden}"),861+usize::from(hidden));t.action(0,Action{card_id:Some(spell),target_id:Some("p0".into()),..Action::new("play")});t.until_pending();t.choose(vec![dead]);t.until_pending();assert!(matches!(&t.room.game.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::DEATH));t.choose(vec!["p2".into()]);t.until_pending();t.choose(vec![enemy.clone()]);assert!(t.room.game.board(&enemy).is_none()&&t.room.game.pending.is_none()&&t.room.game.stack.is_empty());cases.push(t.value());}
 for v in &mut cases{for step in v["steps"].as_array_mut().unwrap(){let room=RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let cmd:RoomCommand=serde_json::from_value(step["command"].clone()).unwrap();let duplicate=room.transition(step["seat"].as_u64().unwrap() as usize,Some(cmd),0).unwrap();assert_eq!(duplicate.outcome,"rejected");assert!(!duplicate.changed&&duplicate.journal.is_empty());assert_eq!(duplicate.state,step["expected"]["state"]);step["duplicate"]=serde_json::to_value(duplicate).unwrap();}}
 let mut bindings=crate::jc066_tests::source_bindings();for(name,bytes)in[("rust-game/src/bq086.rs",include_bytes!("bq086.rs").as_slice()),("rust-game/src/bq086_tests.rs",include_bytes!("bq086_tests.rs").as_slice()),("rust-game/src/cq09.rs",include_bytes!("cq09.rs").as_slice()),("rust-game/src/cq10.rs",include_bytes!("cq10.rs").as_slice()),("rust-game/src/abi112_review_play_tests.rs",include_bytes!("abi112_review_play_tests.rs").as_slice())]{bindings["files"].as_object_mut().unwrap().insert(name.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}
 if let Ok(path)=std::env::var("BQ086_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":bindings,"cases":cases})).unwrap()).unwrap();}
}
#[test]
fn bq086_duplicate_entry_declaration_is_rejected_but_source_departure_keeps_targets(){let(mut g,corpse,host)=entry();let mut bad=g.clone();let ChoiceResolution::Declare{declaration:d,..}=&g.pending.as_ref().unwrap().resolution else{panic!()};bad.effects.push_back(Effect::Declare{declaration:d.clone()});invalid(&g,&bad);choose(&mut g,vec![corpse.clone()]);choose(&mut g,vec![host.clone()]);let source=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();g.regions[0].cards.retain(|c|c.id!=source);restore(&mut g);pass_top(&mut g);assert!(g.sealed_cards.iter().any(|s|s.host_id==host&&s.card.definition=="XQ46"));}
#[test]
fn bq086_real_corpse_seal_emits_existing_industry_observation(){let(mut g,id,corpse,host)=setup();let observer=g.make_card("BQ093",0);g.attachments.push(Attachment{card:observer,host_id:g.regions[0].card.id.clone()});act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});pass_top(&mut g);choose(&mut g,vec![corpse]);choose(&mut g,vec![host.clone()]);pass_top(&mut g);assert!(matches!(&g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==crate::import20_industry::SEALED));let before=g.current_icons(g.board(&host).unwrap().1,0).investigation;choose(&mut g,vec!["accept".into()]);pass_top(&mut g);assert_eq!(g.current_icons(g.board(&host).unwrap().1,0).investigation,before+1);restore(&mut g);}
